def solve():
    import sys
    sys.setrecursionlimit(5000)

    # R(0) = {11a + 20b | a, b >= 0}
    def is_in_R0(n):
        for a in range(n // 11 + 1):
            rem = n - 11 * a
            if rem >= 0 and rem % 20 == 0:
                return True
        return False

    U = []
    for n in range(1, 250): # Frobenius number is 189, so 250 is safe
        if not is_in_R0(n):
            U.append(n)

    # G[U] adjacency and predecessors
    all_preds = {u: [] for u in range(300)}
    for u in range(1, 300):
        if u + 11 < 300:
            all_preds[u + 11].append(u)
        if u + 20 < 300:
            all_preds[u + 20].append(u)

    memo = {}

    def get_count(current_nodes_tuple):
        if not current_nodes_tuple:
            return 1

        if current_nodes_tuple in memo:
            return memo[current_nodes_tuple]

        # current_nodes_tuple is a sorted tuple of nodes in U
        current_nodes = set(current_nodes_tuple)

        # Pick v as the largest node in current_nodes
        # This node has no successors in current_nodes
        v = current_nodes_tuple[-1]

        # Case 1: v is in S'
        # The remaining nodes must be an upward-closed set in current_nodes \ {v}
        nodes_without_v = []
        for x in current_nodes_tuple:
            if x != v:
                nodes_without_v.append(x)
        res1 = get_count(tuple(nodes_without_v))

        # Case 2: v is not in S'
        # All nodes in current_nodes that can reach v must not be in S'
        to_remove = set()
        stack = [v]
        while stack:
            curr = stack.pop()
            if curr not in to_remove:
                to_remove.add(curr)
                for p in all_preds[curr]:
                    if p in current_nodes:
                        stack.append(p)

        nodes_after_removal = []
        for x in current_nodes_tuple:
            if x not in to_remove:
                nodes_after_removal.append(x)
        res2 = get_count(tuple(nodes_after_removal))

        res = res1 + res2
        memo[current_nodes_tuple] = res
        return res

    print(get_count(tuple(sorted(U))))

solve()

